import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.Map;

/** 静态资源缓存键与回源地址派生：Web 缓存投毒防护示例 */
public class AssetCacheKeyService {

    // 私有源锁定表：仅精确命中的内部源允许进入缓存内容与缓存键
    private static final Map<String, String> TRUSTED_ORIGIN = new LinkedHashMap<>();
    static {
        TRUSTED_ORIGIN.put("assets.corp.internal", "https://assets.corp.internal");
        TRUSTED_ORIGIN.put("assets-dr.corp.internal", "https://assets-dr.corp.internal");
    }
    // 影响响应的全部头：必须逐一纳入缓存键，杜绝未键控头投毒
    private static final String[] KEYED_HEADERS = {"X-Forwarded-Host", "X-Forwarded-Proto", "Accept-Encoding"};

    public String buildCacheKey(String path, Map<String, String> headers) throws Exception {
        StringBuilder seed = new StringBuilder(path);
        for (String name : KEYED_HEADERS) {
            seed.append('|').append(name).append('=').append(canonicalize(name, headers.get(name)));
        }
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return HexFormat.of().formatHex(md.digest(seed.toString().getBytes(StandardCharsets.UTF_8)));
    }

    public String buildResourceUrl(String path, Map<String, String> headers) {
        String safePath = path.startsWith("/") ? path : "/" + path;
        String host = canonicalize("X-Forwarded-Host", headers.get("X-Forwarded-Host"));
        return TRUSTED_ORIGIN.get(host) + safePath;
    }

    // 显式固定解析顺序：首个逗号分段 -> 小写 -> 锁定表精确匹配，未命中回退默认源
    static String canonicalize(String header, String raw) {
        String v = raw == null ? "" : raw.split(",")[0].trim().toLowerCase(java.util.Locale.ROOT);
        if ("X-Forwarded-Host".equals(header)) {
            return TRUSTED_ORIGIN.containsKey(v) ? v : "assets.corp.internal";
        }
        if ("X-Forwarded-Proto".equals(header)) {
            return "https"; // 协议钉死，忽略外部可控取值
        }
        return v.isEmpty() ? "none" : v;
    }
}

package main
import (
	"crypto/sha256"
	"io"
	"net/http"
	"strings"
	"sync"
)
// 影响响应内容的全部请求头：缓存键完整覆盖，并按本切片固定顺序解析
var influential = []string{"Accept", "Accept-Language", "X-Forwarded-Host", "X-Forwarded-Proto"}
// 源站锁定为内网私有地址，绝不取自用户可控的 X-Forwarded-Host
const originLocked = "http://10.0.0.2:8080"
type entry struct{ body []byte; sum [32]byte }
var mu sync.RWMutex
var store = map[string]entry{}

func cacheKey(r *http.Request) string {
	parts := []string{r.Method, r.URL.Path, r.URL.RawQuery}
	for _, h := range influential {
		parts = append(parts, strings.ToLower(h)+"="+strings.ToLower(strings.TrimSpace(r.Header.Get(h))))
	}
	return string(sha256.Sum256([]byte(strings.Join(parts, "\x00")))[:])
}

func handler(w http.ResponseWriter, r *http.Request) {
	key := cacheKey(r)
	mu.RLock()
	e, hit := store[key]
	mu.RUnlock()
	if hit && sha256.Sum256(e.body) == e.sum { // 哈希校验通过才回放缓存
		w.Write(e.body)
		return
	}
	resp, err := http.Get(originLocked + r.URL.EscapedPath() + "?" + r.URL.RawQuery)
	if err != nil {
		http.Error(w, "upstream", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	mu.Lock()
	store[key] = entry{body, sha256.Sum256(body)}
	mu.Unlock()
	w.Write(body)
}

package main
import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"html"
	"net/http"
	"os"
	"strings"
	"sync"
)
const pinnedOrigin = "https://shop.internal.example" // 私有源锁定：出站绝对链接只认该基准，请求头无法改写
// varyHeaders 覆盖影响响应内容的全部头，顺序在此显式固定，缓存键按该顺序派生
var varyHeaders = []string{"Accept-Encoding", "X-Forwarded-Proto", "X-Forwarded-Host"}
var macKey = []byte(os.Getenv("CACHE_HMAC_KEY")) // 签名密钥仅从环境注入，代码内无明文凭据
type entry struct{ body, tag []byte }
func cacheKey(r *http.Request) string {
	parts := []string{r.Method, strings.ToLower(r.URL.Path), r.URL.RawQuery}
	for _, h := range varyHeaders {
		parts = append(parts, h+"="+r.Header.Get(h))
	}
	sum := sha256.Sum256([]byte(strings.Join(parts, "\x1f")))
	return hex.EncodeToString(sum[:])
}
func handler(store *sync.Map) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := cacheKey(r)
		w.Header().Set("Vary", strings.Join(varyHeaders, ", "))
		if raw, ok := store.Load(id); ok {
			e := raw.(entry)
			mac := hmac.New(sha256.New, macKey)
			mac.Write(e.body)
			if hmac.Equal(e.tag, mac.Sum(nil)) {
				w.Write(e.body)
				return
			}
			store.Delete(id) // 哈希校验失败即丢弃，可疑条目绝不回放
		}
		body := []byte(`<a href="` + pinnedOrigin + html.EscapeString(r.URL.Path) + `">home</a>`)
		mac := hmac.New(sha256.New, macKey)
		mac.Write(body)
		store.Store(id, entry{body: body, tag: mac.Sum(nil)})
		w.Write(body)
	}
}
